import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.Document;

public class TextNodeTest {

    @Test
    public void createTextNodeFromEmptyString_ReturnsEmptyTextNode() {
        TextNode textNode = TextNode.createFromEncoded("");
        assertTrue(textNode.text().isEmpty());
    }

    @Test
    public void createTextNodeFromSingleCharacter_ReturnsSingleCharTextNode() {
        String charStr = "a";
        TextNode textNode = TextNode.createFromEncoded(charStr);
        assertEquals(1, textNode.text().length());
    }

    @Test
    public void normaliseWhitespace_LeadingSpace_ReturnsStringWithSpace() {
        String originalText = "  a ";
        String expectedText = " a ";
        assertEquals(expectedText, TextNode.normaliseWhitespace(originalText));
    }

    @Test
    public void stripLeadingWhitespace_LeadsToTrimming() {
        String originalText = "   a ";
        String expectedText = "a";
        assertEquals(expectedText, TextNode.stripLeadingWhitespace(originalText));
    }

    @Test
    public void lastCharIsWhitespace_EmptyStringBuilder_ReturnsTrue() {
        StringBuilder sb = new StringBuilder();
        assertTrue(TextNode.lastCharIsWhitespace(sb));
    }

    @Test
    public void textTextNodeTextCannotBeEmpty_ThrowsNullPointerExceptionWhenSplitting() {
        TextNode textNode = new TextNode("");
        assertThrows(NullPointerException.class, () -> textNode.splitText(0));
    }
}

